import { useCallback, useEffect, useMemo, useState, type FormEvent } from 'react';
import { AlertTriangle, ArrowUpRight, BadgeCheck, Check, ChevronDown, CircleDollarSign, ClipboardList, EyeOff, LogOut, Package, Pencil, Plus, RefreshCw, Save, Settings, ShieldCheck, Star, Trash2, UploadCloud, X } from 'lucide-react';
import type { Category, OrderRecord, Product } from '../types';
import { callFunction, isSupabaseConfigured, money, supabase } from '../lib/supabase';

interface AdminProduct extends Product { category_id?: string | null; brand_id?: string | null }
interface SettingRow { key: string; value: Record<string, unknown>; is_public: boolean }
interface ShippingRow { id: string; name: string; is_active: boolean; cost_mode: 'fixed'|'confirm'|'free'; cost: number|null; estimated_days: string|null }
interface ReviewRow { id: string; display_name: string; rating: number; comment: string; created_at: string; is_approved: boolean; is_verified_purchase: boolean; products?: { name: string } }
interface PromotionRow { id: string; title: string; description: string | null; starts_at: string | null; ends_at: string | null; is_active: boolean; created_at: string }
interface FAQItem { question: string; answer: string }
interface AdminPayload { products?: AdminProduct[]; orders?: OrderRecord[]; settings?: SettingRow[]; categories?: Category[]; shipping?: ShippingRow[]; reviews?: ReviewRow[]; promotions?: PromotionRow[]; stats?: Array<{ id: string; subtotal: number; total_amount: number|null; payment_status: string; status: string; created_at: string }> }
interface ProductForm { id?: string; name: string; sku: string; short_description: string; description: string; category_id: string; brand: string; price: string; sale_price: string; stock: string; image_urls: string; variants_text: string; is_published: boolean; is_featured: boolean }
const emptyProduct: ProductForm = { name: '', sku: '', short_description: '', description: '', category_id: '', brand: '', price: '', sale_price: '', stock: '0', image_urls: '', variants_text: '', is_published: false, is_featured: false };
const orderStatuses = [
  ['pending_confirmation','Pendiente de confirmación'],['pending_payment','Pendiente de pago'],['payment_confirmed','Pago confirmado'],['preparing','En preparación'],['shipped','Enviado'],['delivered','Entregado'],['cancelled','Cancelado'],
] as const;
const paymentStatuses = [['pending','Pendiente'],['proof_received','Comprobante recibido'],['confirmed','Confirmado'],['rejected','Rechazado'],['refunded','Reembolsado']] as const;
function dateTimeLocal(value: string | null | undefined): string { if (!value) return ''; const date = new Date(value); if (Number.isNaN(date.getTime())) return ''; return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0,16); }

function objectValue(row: SettingRow | undefined): Record<string, unknown> { return row?.value && typeof row.value === 'object' ? row.value : {}; }
function valueText(value: unknown, fallback = ''): string { return typeof value === 'string' ? value : fallback; }
function parseVariants(value: string) {
  return value.split('\n').map((line) => line.trim()).filter(Boolean).map((line) => {
    const [label = '', stockText = '0', priceText = '', sku = ''] = line.split('|').map((part) => part.trim());
    return { label, stock: Number(stockText || 0), price_override: priceText ? Number(priceText) : null, sku };
  });
}

export function AdminPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState<'loading'|'signed-out'|'loading-admin'|'authorized'|'not-authorized'>('loading');
  const [tab, setTab] = useState<'dashboard'|'products'|'orders'|'reviews'|'settings'>('dashboard');
  const [data, setData] = useState<AdminPayload>({});
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [productForm, setProductForm] = useState<ProductForm>(emptyProduct);
  const [editingProduct, setEditingProduct] = useState(false);
  const [searchProducts, setSearchProducts] = useState('');
  const [searchOrders, setSearchOrders] = useState('');
  const [orderDrafts, setOrderDrafts] = useState<Record<string, { status: string; payment_status: string; shipping_cost: string; tracking_number: string; internal_notes: string }>>({});
  const [businessForm, setBusinessForm] = useState({ name: 'Margarita’s Glow', instagram: 'https://www.instagram.com/margaritasglow.uy/', phone: '099 782 589', location: 'Villa Constitución, Salto, Uruguay', shipping_message: 'Envíos a todo Uruguay' });
  const [storefrontForm, setStorefrontForm] = useState({ hero_title: 'Tu próximo favorito está acá', hero_subtitle: 'Maquillaje, belleza y accesorios elegidos con cariño.', announcement: 'Envíos a todo Uruguay', show_featured: true });
  const [bankForm, setBankForm] = useState({ holder: 'Melany Cardozo', bank: 'BROU', account_number: '110984406-00001', instructions: 'Después de realizar la transferencia, enviá el comprobante por WhatsApp.' });
  const [newCategory, setNewCategory] = useState('');
  const [shippingDrafts, setShippingDrafts] = useState<Record<string, { name: string; is_active: boolean; cost_mode: 'fixed'|'confirm'|'free'; cost: string; estimated_days: string }>>({});
  const [policyDrafts, setPolicyDrafts] = useState({ policy_privacy: '', policy_terms: '', policy_returns: '' });
  const [faqDrafts, setFaqDrafts] = useState<FAQItem[]>([]);
  const [promotionDraft, setPromotionDraft] = useState({ id: '', title: '', description: '', starts_at: '', ends_at: '', is_active: false });
  const [uploading, setUploading] = useState(false);

  const loadData = useCallback(async () => {
    setStatus('loading-admin'); setError('');
    try {
      const [products, orders, settings] = await Promise.all([
        callFunction<{ products: AdminProduct[] }>('admin-products', undefined, 'GET'),
        callFunction<{ orders: OrderRecord[] }>('admin-orders', undefined, 'GET'),
        callFunction<AdminPayload>('admin-settings', undefined, 'GET'),
      ]);
      const next: AdminPayload = { ...settings, products: products.products, orders: orders.orders };
      setData(next);
      const settingsRows = next.settings ?? [];
      const business = objectValue(settingsRows.find((row) => row.key === 'business_profile'));
      const storefront = objectValue(settingsRows.find((row) => row.key === 'storefront'));
      const bank = objectValue(settingsRows.find((row) => row.key === 'payment_details'));
      setBusinessForm({ name: valueText(business.name, 'Margarita’s Glow'), instagram: valueText(business.instagram, 'https://www.instagram.com/margaritasglow.uy/'), phone: valueText(business.phone, '099 782 589'), location: valueText(business.location, 'Villa Constitución, Salto, Uruguay'), shipping_message: valueText(business.shipping_message, 'Envíos a todo Uruguay') });
      setStorefrontForm({ hero_title: valueText(storefront.hero_title, 'Tu próximo favorito está acá'), hero_subtitle: valueText(storefront.hero_subtitle, 'Maquillaje, belleza y accesorios elegidos con cariño.'), announcement: valueText(storefront.announcement, 'Envíos a todo Uruguay'), show_featured: storefront.show_featured !== false });
      setBankForm({ holder: valueText(bank.holder, 'Melany Cardozo'), bank: valueText(bank.bank, 'BROU'), account_number: valueText(bank.account_number, '110984406-00001'), instructions: valueText(bank.instructions, 'Después de realizar la transferencia, enviá el comprobante por WhatsApp.') });
      setPolicyDrafts({ policy_privacy: valueText(objectValue(settingsRows.find((row) => row.key === 'policy_privacy')).content), policy_terms: valueText(objectValue(settingsRows.find((row) => row.key === 'policy_terms')).content), policy_returns: valueText(objectValue(settingsRows.find((row) => row.key === 'policy_returns')).content) });
      const faqValue = objectValue(settingsRows.find((row) => row.key === 'faq'));
      const faqItems = Array.isArray(faqValue.items) ? faqValue.items.filter((item): item is { question: string; answer: string } => Boolean(item && typeof item === 'object' && typeof (item as Record<string, unknown>).question === 'string' && typeof (item as Record<string, unknown>).answer === 'string')).map((item) => ({ question: item.question, answer: item.answer })) : [];
      setFaqDrafts(faqItems);
      const drafts: typeof shippingDrafts = {};
      for (const row of next.shipping ?? []) drafts[row.id] = { name: row.name, is_active: row.is_active, cost_mode: row.cost_mode, cost: row.cost === null ? '' : String(row.cost), estimated_days: row.estimated_days || '' };
      setShippingDrafts(drafts);
      setStatus('authorized');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'No fue posible validar los permisos administrativos.');
      setStatus('not-authorized');
    }
  }, []);

  useEffect(() => {
    if (!supabase) { setStatus('signed-out'); return; }
    let active = true;
    supabase.auth.getSession().then(({ data: sessionData }) => {
      if (!active) return;
      if (sessionData.session) void loadData(); else setStatus('signed-out');
    }).catch(() => { if (active) setStatus('signed-out'); });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      if (!session) { setStatus('signed-out'); setData({}); }
      else void loadData();
    });
    return () => { active = false; listener.subscription.unsubscribe(); };
  }, [loadData]);

  async function login(event: FormEvent) {
    event.preventDefault(); setError(''); setBusy(true);
    try {
      if (!supabase) throw new Error('Primero configurá las variables públicas de Supabase.');
      const { error: authError } = await supabase.auth.signInWithPassword({ email, password });
      if (authError) throw new Error('No pudimos iniciar sesión. Revisá el correo y la contraseña.');
      setPassword(''); await loadData();
    } catch (err) { setError(err instanceof Error ? err.message : 'No se pudo iniciar sesión.'); setStatus('signed-out'); }
    finally { setBusy(false); }
  }
  async function logout() { await supabase?.auth.signOut(); setData({}); setStatus('signed-out'); }
  function notify(text: string) { setMessage(text); setError(''); window.setTimeout(() => setMessage(''), 3000); }
  async function refresh() { setBusy(true); try { await loadData(); notify('Datos actualizados.'); } catch { setError('No se pudieron actualizar los datos.'); } finally { setBusy(false); } }

  function beginCreateProduct() { setProductForm(emptyProduct); setEditingProduct(false); setTab('products'); window.setTimeout(() => document.getElementById('product-editor')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); }
  function beginEditProduct(product: AdminProduct) {
    const variants = (product.product_variants ?? []).filter((item) => item.is_active).map((variant) => {
      const stock = (product.inventory ?? []).find((row) => row.variant_id === variant.id)?.stock ?? 0;
      return `${variant.label}|${stock}|${variant.price_override ?? ''}|${variant.sku ?? ''}`;
    }).join('\n');
    const baseStock = (product.inventory ?? []).find((row) => !row.variant_id)?.stock ?? 0;
    setProductForm({ id: product.id, name: product.name, sku: product.sku || '', short_description: product.short_description || '', description: product.description || '', category_id: product.category_id || product.categories?.id || '', brand: product.brands?.name || '', price: String(product.price), sale_price: product.sale_price === null || product.sale_price === undefined ? '' : String(product.sale_price), stock: String(baseStock), image_urls: (product.product_images ?? []).sort((a,b) => (a.position ?? 0) - (b.position ?? 0)).map((image) => image.image_url).join('\n'), variants_text: variants, is_published: product.is_published, is_featured: product.is_featured });
    setEditingProduct(true); setTab('products'); window.setTimeout(() => document.getElementById('product-editor')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
  }
  async function saveProduct(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const image_urls = productForm.image_urls.split('\n').map((url) => url.trim()).filter(Boolean);
      const variants = parseVariants(productForm.variants_text);
      if (variants.some((item) => !item.label || !Number.isInteger(item.stock) || item.stock < 0 || (item.price_override !== null && !Number.isFinite(item.price_override)))) throw new Error('Revisá el formato de las variantes. Usá: Nombre|Stock|Precio opcional|SKU opcional.');
      const payload = { ...(productForm.id ? { id: productForm.id } : {}), name: productForm.name, sku: productForm.sku, short_description: productForm.short_description, description: productForm.description, category_id: productForm.category_id || null, brand: productForm.brand, price: Number(productForm.price), sale_price: productForm.sale_price === '' ? null : Number(productForm.sale_price), stock: Number(productForm.stock || 0), image_urls, variants, is_published: productForm.is_published, is_featured: productForm.is_featured };
      await callFunction('admin-products', { product: payload }, 'POST');
      notify(productForm.id ? 'Producto actualizado.' : 'Producto creado.'); setProductForm(emptyProduct); setEditingProduct(false); await loadData();
    } catch (err) { setError(err instanceof Error ? err.message : 'No se pudo guardar el producto.'); }
    finally { setBusy(false); }
  }
  async function uploadImage(file: File | undefined) {
    if (!file) return; setUploading(true); setError('');
    try {
      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve, reject) => { reader.onload = () => resolve(String(reader.result).split(',')[1] || ''); reader.onerror = () => reject(new Error('No se pudo leer el archivo.')); reader.readAsDataURL(file); });
      const result = await callFunction<{ image_url: string; storage_path: string }>('admin-media', { file_name: file.name, mime_type: file.type, base64 });
      setProductForm((current) => ({ ...current, image_urls: [current.image_urls.trim(), result.image_url].filter(Boolean).join('\n') })); notify('Imagen subida. Guardá el producto para asociarla al catálogo.');
    } catch (err) { setError(err instanceof Error ? err.message : 'No se pudo subir la imagen.'); }
    finally { setUploading(false); }
  }
  async function deleteStorageImage(url: string) {
    try {
      const parsed = new URL(url); const marker = '/storage/v1/object/public/product-images/';
      if (!parsed.pathname.includes(marker)) { notify('La imagen se quitará del producto, pero no parece estar almacenada en el bucket de esta tienda.'); return; }
      const storage_path = decodeURIComponent(parsed.pathname.split(marker)[1]);
      await callFunction('admin-media', { action: 'delete', storage_path }); notify('Archivo eliminado del almacenamiento.');
    } catch (err) { setError(err instanceof Error ? err.message : 'No se pudo eliminar el archivo.'); }
  }
  async function unpublishProduct(product: AdminProduct) {
    if (!window.confirm(`¿Despublicar “${product.name}”? El producto dejará de mostrarse en la tienda, pero se conserva el historial.`)) return;
    setBusy(true); try { await callFunction('admin-products', { id: product.id }, 'DELETE'); await loadData(); notify('Producto despublicado.'); } catch (err) { setError(err instanceof Error ? err.message : 'No se pudo despublicar.'); } finally { setBusy(false); }
  }
  async function saveOrder(orderId: string) {
    const draft = orderDrafts[orderId]; if (!draft) return;
    setBusy(true); setError('');
    try { await callFunction('admin-orders', { id: orderId, status: draft.status, payment_status: draft.payment_status, shipping_cost: draft.shipping_cost.trim() === '' ? null : Number(draft.shipping_cost), tracking_number: draft.tracking_number, internal_notes: draft.internal_notes }, 'PATCH'); await loadData(); notify('Pedido actualizado.'); }
    catch (err) { setError(err instanceof Error ? err.message : 'No se pudo actualizar el pedido.'); } finally { setBusy(false); }
  }
  async function saveSetting(key: string, value: Record<string, unknown>) {
    setBusy(true); setError(''); try { await callFunction('admin-settings', { action: 'save_setting', key, value }, 'POST'); await loadData(); notify('Configuración guardada.'); }
    catch (err) { setError(err instanceof Error ? err.message : 'No se pudo guardar.'); } finally { setBusy(false); }
  }
  async function saveSettingsBatch(entries: Array<{ key: string; value: Record<string, unknown> }>) {
    setBusy(true); setError('');
    try { for (const entry of entries) await callFunction('admin-settings', { action: 'save_setting', ...entry }, 'POST'); await loadData(); notify('Textos legales guardados.'); }
    catch (err) { setError(err instanceof Error ? err.message : 'No se pudieron guardar los textos.'); }
    finally { setBusy(false); }
  }
  async function saveCategory(category?: Category) {
    const name = category?.name ?? newCategory.trim(); if (!name) return;
    setBusy(true); try { await callFunction('admin-settings', { action: 'save_category', ...(category ? { id: category.id } : {}), name, is_active: category?.is_active ?? true, sort_order: category?.sort_order ?? (data.categories?.length || 0) + 1 }, 'POST'); setNewCategory(''); await loadData(); notify('Categoría guardada.'); }
    catch (err) { setError(err instanceof Error ? err.message : 'No se pudo guardar la categoría.'); } finally { setBusy(false); }
  }
  async function saveShipping(row: ShippingRow) {
    const draft = shippingDrafts[row.id]; if (!draft) return;
    setBusy(true); try { await callFunction('admin-settings', { action: 'save_shipping', id: row.id, name: draft.name, is_active: draft.is_active, cost_mode: draft.cost_mode, cost: draft.cost.trim() ? Number(draft.cost) : null, estimated_days: draft.estimated_days || null }, 'POST'); await loadData(); notify('Transporte actualizado.'); }
    catch (err) { setError(err instanceof Error ? err.message : 'No se pudo actualizar el transporte.'); } finally { setBusy(false); }
  }
  async function moderateReview(review: ReviewRow, is_approved: boolean) {
    setBusy(true); try { await callFunction('admin-settings', { action: 'review_moderation', id: review.id, is_approved }, 'POST'); await loadData(); notify(is_approved ? 'Opinión publicada.' : 'Opinión ocultada.'); }
    catch (err) { setError(err instanceof Error ? err.message : 'No se pudo moderar la opinión.'); } finally { setBusy(false); }
  }
  async function savePromotion(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError('');
    try {
      await callFunction('admin-settings', { action: 'save_promotion', ...(promotionDraft.id ? { id: promotionDraft.id } : {}), title: promotionDraft.title, description: promotionDraft.description, starts_at: promotionDraft.starts_at ? new Date(promotionDraft.starts_at).toISOString() : null, ends_at: promotionDraft.ends_at ? new Date(promotionDraft.ends_at).toISOString() : null, is_active: promotionDraft.is_active }, 'POST');
      setPromotionDraft({ id: '', title: '', description: '', starts_at: '', ends_at: '', is_active: false });
      await loadData(); notify('Promoción guardada.');
    } catch (err) { setError(err instanceof Error ? err.message : 'No se pudo guardar la promoción.'); } finally { setBusy(false); }
  }
  async function deletePromotion(promotion: PromotionRow) {
    if (!window.confirm(`¿Eliminar la promoción “${promotion.title}”?`)) return;
    setBusy(true); try { await callFunction('admin-settings', { action: 'delete_promotion', id: promotion.id }, 'POST'); if (promotionDraft.id === promotion.id) setPromotionDraft({ id: '', title: '', description: '', starts_at: '', ends_at: '', is_active: false }); await loadData(); notify('Promoción eliminada.'); }
    catch (err) { setError(err instanceof Error ? err.message : 'No se pudo eliminar la promoción.'); } finally { setBusy(false); }
  }

  const filteredProducts = useMemo(() => (data.products ?? []).filter((product) => `${product.name} ${product.sku || ''} ${product.brands?.name || ''}`.toLowerCase().includes(searchProducts.toLowerCase())), [data.products, searchProducts]);
  const filteredOrders = useMemo(() => (data.orders ?? []).filter((order) => `${order.order_number} ${order.customers?.full_name || ''} ${order.customers?.phone || ''} ${order.status}`.toLowerCase().includes(searchOrders.toLowerCase())), [data.orders, searchOrders]);
  const confirmedSales = (data.stats ?? []).filter((order) => order.payment_status === 'confirmed').reduce((sum, order) => sum + Number(order.total_amount ?? order.subtotal), 0);
  const pendingOrders = (data.orders ?? []).filter((order) => !['delivered','cancelled'].includes(order.status)).length;

  if (!isSupabaseConfigured || status === 'signed-out') return <main className="container page-main admin-entry"><div className="admin-login-card"><img src="/images/brand-mark.png" alt=""/><span className="eyebrow">ESPACIO PRIVADO</span><h1>Administración</h1><p>Ingresá con la cuenta autorizada para gestionar Margarita’s Glow.</p>{!isSupabaseConfigured ? <div className="error-banner"><AlertTriangle size={18}/> La conexión con Supabase no está configurada. Completá el archivo <code>.env</code> con la URL y la clave pública para habilitar el inicio de sesión.</div> : <form onSubmit={login} className="admin-login-form"><label>Correo electrónico<input required type="email" autoComplete="username" value={email} onChange={(e) => setEmail(e.target.value)}/></label><label>Contraseña<input required type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)}/></label>{error && <p className="form-message form-message--error">{error}</p>}<button className="button button-primary button-full" disabled={busy}>{busy ? 'Ingresando…' : 'Iniciar sesión'}</button></form>}<p className="admin-login-hint"><ShieldCheck size={16}/> El acceso requiere una cuenta creada en Supabase y registrada como administradora por la propietaria.</p></div></main>;
  if (status === 'loading' || status === 'loading-admin') return <main className="container page-main"><div className="loading-row"><span className="spinner"/> Validando acceso administrativo…</div></main>;
  if (status === 'not-authorized') return <main className="container page-main admin-entry"><div className="admin-login-card"><div className="admin-warning-icon"><AlertTriangle/></div><h1>Acceso no autorizado</h1><p>{error || 'Tu usuario inició sesión, pero todavía no tiene permisos para administrar esta tienda.'}</p><p>La cuenta debe agregarse a <code>public.admin_users</code> mediante el procedimiento seguro explicado en README.md.</p><div className="admin-login-actions"><button className="button button-outline" onClick={logout}>Cerrar sesión</button><button className="button button-primary" onClick={loadData}>Volver a comprobar</button></div></div></main>;

  return <main className="admin-shell">
    <aside className="admin-sidebar"><div className="admin-sidebar__brand"><img src="/images/brand-mark.png" alt=""/><div><strong>Margarita’s Glow</strong><small>Panel de administración</small></div></div><nav className="admin-nav" aria-label="Secciones de administración">{([['dashboard',ClipboardList,'Resumen'],['products',Package,'Productos e inventario'],['orders',CircleDollarSign,'Pedidos y pagos'],['reviews',Star,'Opiniones'],['settings',Settings,'Configuración']] as const).map(([key, Icon, label]) => <button key={key} className={tab === key ? 'is-active' : ''} onClick={() => setTab(key)}><Icon size={18}/>{label}</button>)}</nav><div className="admin-sidebar__bottom"><a href="/" target="_blank" rel="noreferrer"><ArrowUpRight size={16}/> Ver tienda</a><button onClick={logout}><LogOut size={17}/> Cerrar sesión</button></div></aside>
    <section className="admin-content"><header className="admin-topbar"><div><span className="eyebrow">MARGARITA’S GLOW</span><h1>{({dashboard:'Resumen de la tienda',products:'Productos e inventario',orders:'Pedidos y pagos',reviews:'Opiniones de clientas',settings:'Configuración de la tienda'} as const)[tab]}</h1></div><button className="button button-outline button-small" onClick={refresh} disabled={busy}><RefreshCw size={15}/> Actualizar</button></header>
      {message && <div className="admin-alert admin-alert--success"><Check size={17}/>{message}<button onClick={() => setMessage('')} aria-label="Cerrar mensaje"><X size={15}/></button></div>}{error && <div className="admin-alert admin-alert--error"><AlertTriangle size={17}/>{error}<button onClick={() => setError('')} aria-label="Cerrar error"><X size={15}/></button></div>}
      {tab === 'dashboard' && <div className="admin-dashboard"><div className="admin-stat-grid"><article className="admin-stat"><span>Pedidos registrados</span><strong>{data.orders?.length ?? 0}</strong><small>Todos los estados</small><ClipboardList/></article><article className="admin-stat"><span>Por gestionar</span><strong>{pendingOrders}</strong><small>Sin entregar o cancelar</small><Package/></article><article className="admin-stat"><span>Ventas con pago confirmado</span><strong>{money(confirmedSales)}</strong><small>Según registros marcados como pagados</small><CircleDollarSign/></article><article className="admin-stat"><span>Productos publicados</span><strong>{data.products?.filter((product) => product.is_published).length ?? 0}</strong><small>En el catálogo público</small><BadgeCheck/></article></div><div className="admin-panel"><div className="admin-panel__heading"><div><h2>Pedidos recientes</h2><p>Los pedidos no se consideran pagados hasta confirmar la transferencia.</p></div><button className="text-link" onClick={() => setTab('orders')}>Ver pedidos <ChevronDown size={16}/></button></div>{(data.orders ?? []).length ? <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Subtotal</th><th>Estado</th></tr></thead><tbody>{[...(data.orders ?? [])].slice(0,6).map((order) => <tr key={order.id}><td><strong>{order.order_number}</strong></td><td>{order.customers?.full_name || '—'}</td><td>{new Date(order.created_at).toLocaleDateString('es-UY')}</td><td>{money(order.subtotal)}</td><td><span className={`status-pill status-pill--${order.status}`}>{orderStatuses.find(([value]) => value === order.status)?.[1] || order.status}</span></td></tr>)}</tbody></table></div> : <div className="soft-note">Todavía no hay pedidos. Cuando una clienta complete un pedido, aparecerá acá.</div>}</div><div className="admin-panel admin-quick-actions"><h2>Acciones rápidas</h2><button className="quick-action" onClick={beginCreateProduct}><Plus/><span><strong>Cargar producto</strong><small>Sumá una referencia al catálogo</small></span><ArrowUpRight/></button><button className="quick-action" onClick={() => setTab('orders')}><CircleDollarSign/><span><strong>Revisar pedidos</strong><small>Actualizar pagos, envíos y estados</small></span><ArrowUpRight/></button><button className="quick-action" onClick={() => setTab('settings')}><Settings/><span><strong>Editar la tienda</strong><small>Contacto, textos, categorías y transporte</small></span><ArrowUpRight/></button></div></div>}

      {tab === 'products' && <div className="admin-products-tab"><div className="admin-panel"><div className="admin-panel__heading"><div><h2>Tu catálogo</h2><p>{data.products?.length ?? 0} referencias registradas</p></div><button className="button button-primary button-small" onClick={beginCreateProduct}><Plus size={16}/> Nuevo producto</button></div><div className="admin-search"><input value={searchProducts} onChange={(e) => setSearchProducts(e.target.value)} placeholder="Buscar por nombre, SKU o marca…" aria-label="Buscar productos en administración"/></div>{filteredProducts.length ? <div className="admin-products-list">{filteredProducts.map((product) => { const stock = (product.inventory ?? []).reduce((sum, row) => sum + Number(row.stock), 0); const image = product.product_images?.[0]?.image_url; return <article className="admin-product-row" key={product.id}><div className="admin-product-thumb">{image ? <img src={image} alt=""/> : <img src="/images/brand-mark.png" alt=""/>}</div><div className="admin-product-row__main"><strong>{product.name}</strong><span>{product.brands?.name || 'Sin marca'} · {product.categories?.name || 'Sin categoría'}</span><small>SKU: {product.sku || '—'} · Stock: {stock}</small></div><div className="admin-product-row__price"><strong>{money(product.sale_price ?? product.price)}</strong>{product.sale_price !== null && product.sale_price !== undefined && <del>{money(product.price)}</del>}<span className={product.is_published ? 'product-state is-published' : 'product-state'}>{product.is_published ? 'Publicado' : 'Borrador'}</span></div><div className="admin-row-actions"><button onClick={() => beginEditProduct(product)} aria-label={`Editar ${product.name}`} title="Editar"><Pencil size={16}/></button>{product.is_published && <button onClick={() => void unpublishProduct(product)} aria-label={`Despublicar ${product.name}`} title="Despublicar"><EyeOff size={16}/></button>}</div></article>; })}</div> : <div className="soft-note">No hay coincidencias. Podés cargar un producto nuevo.</div>}</div>
        <form id="product-editor" className="admin-panel admin-product-editor" onSubmit={saveProduct}><div className="admin-panel__heading"><div><h2>{editingProduct ? 'Editar producto' : 'Nuevo producto'}</h2><p>Los cambios se guardan en Supabase; no necesitás editar código.</p></div>{editingProduct && <button type="button" className="icon-button" onClick={() => { setProductForm(emptyProduct); setEditingProduct(false); }} aria-label="Cancelar edición"><X/></button>}</div><div className="form-grid form-grid--two"><label>Nombre del producto *<input required minLength={2} maxLength={180} value={productForm.name} onChange={(e) => setProductForm({ ...productForm, name: e.target.value })}/></label><label>SKU<input maxLength={80} value={productForm.sku} onChange={(e) => setProductForm({ ...productForm, sku: e.target.value })}/></label><label>Marca<input maxLength={100} value={productForm.brand} onChange={(e) => setProductForm({ ...productForm, brand: e.target.value })}/></label><label>Categoría<select value={productForm.category_id} onChange={(e) => setProductForm({ ...productForm, category_id: e.target.value })}><option value="">Sin categoría</option>{(data.categories ?? []).map((category) => <option value={category.id} key={category.id}>{category.name}{category.is_active === false ? ' (inactiva)' : ''}</option>)}</select></label><label>Precio habitual (UYU) *<input required type="number" min="0" step="0.01" value={productForm.price} onChange={(e) => setProductForm({ ...productForm, price: e.target.value })}/></label><label>Precio promocional (opcional)<input type="number" min="0" step="0.01" value={productForm.sale_price} onChange={(e) => setProductForm({ ...productForm, sale_price: e.target.value })}/></label><label>Stock del producto sin variantes<input type="number" min="0" step="1" value={productForm.stock} onChange={(e) => setProductForm({ ...productForm, stock: e.target.value })}/></label><label className="form-span-two">Descripción corta<input maxLength={300} value={productForm.short_description} onChange={(e) => setProductForm({ ...productForm, short_description: e.target.value })}/></label><label className="form-span-two">Descripción completa<textarea rows={4} maxLength={5000} value={productForm.description} onChange={(e) => setProductForm({ ...productForm, description: e.target.value })}/></label></div>
          <div className="admin-subsection"><div><h3>Fotos del producto</h3><p>Subí JPG, PNG, WEBP o AVIF de hasta 5 MB, o pegá URL públicas una por línea.</p></div><label className="upload-button"><UploadCloud size={17}/>{uploading ? 'Subiendo…' : 'Subir imagen'}<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" disabled={uploading} onChange={(e) => { void uploadImage(e.target.files?.[0]); e.currentTarget.value = ''; }}/></label></div><textarea className="image-url-textarea" rows={3} value={productForm.image_urls} onChange={(e) => setProductForm({ ...productForm, image_urls: e.target.value })} placeholder="https://… (una URL por línea)" aria-label="URL de imágenes del producto"/>{productForm.image_urls.split('\n').map((url) => url.trim()).filter(Boolean).map((url) => <div className="image-url-row" key={url}><a href={url} target="_blank" rel="noreferrer" className="truncate-url">{url}</a><button type="button" className="remove-link" onClick={() => { void deleteStorageImage(url); setProductForm((current) => ({ ...current, image_urls: current.image_urls.split('\n').filter((line) => line.trim() !== url).join('\n') })); }} title="Eliminar este archivo de Storage si pertenece a esta tienda" aria-label="Eliminar imagen"><Trash2 size={15}/></button></div>)}
          <div className="admin-subsection"><div><h3>Variantes (opcional)</h3><p>Una por línea: <code>Etiqueta|Stock|Precio opcional|SKU opcional</code>. Si no tiene variantes, dejá vacío.</p></div></div><textarea rows={4} value={productForm.variants_text} onChange={(e) => setProductForm({ ...productForm, variants_text: e.target.value })} placeholder={'Tono 01|5|250|TONO-01\nTono 02|2||TONO-02'} aria-label="Variantes del producto"/>
          <div className="checkbox-line"><label><input type="checkbox" checked={productForm.is_published} onChange={(e) => setProductForm({ ...productForm, is_published: e.target.checked })}/> Publicar en la tienda</label><label><input type="checkbox" checked={productForm.is_featured} onChange={(e) => setProductForm({ ...productForm, is_featured: e.target.checked })}/> Mostrar en destacados</label></div><div className="form-actions"><button type="button" className="button button-outline" onClick={() => { setProductForm(emptyProduct); setEditingProduct(false); }}>Limpiar</button><button className="button button-primary" disabled={busy}><Save size={16}/>{busy ? 'Guardando…' : 'Guardar producto'}</button></div></form>
      </div>}

      {tab === 'orders' && <div className="admin-orders-tab"><div className="admin-panel"><div className="admin-panel__heading"><div><h2>Pedidos recibidos</h2><p>Los estados deben reflejar lo que ocurrió realmente.</p></div><span className="status-pill">{filteredOrders.length} pedido(s)</span></div><div className="admin-search"><input value={searchOrders} onChange={(e) => setSearchOrders(e.target.value)} placeholder="Buscar pedido, cliente, teléfono o estado…" aria-label="Buscar pedidos"/></div>{filteredOrders.length ? <div className="admin-orders-list">{filteredOrders.map((order) => {
          const draft = orderDrafts[order.id] ?? { status: order.status, payment_status: order.payment_status, shipping_cost: order.shipping_cost === null || order.shipping_cost === undefined ? '' : String(order.shipping_cost), tracking_number: order.tracking_number || '', internal_notes: order.internal_notes || '' };
          const updateDraft = (key: keyof typeof draft, value: string) => setOrderDrafts((current) => ({ ...current, [order.id]: { ...(current[order.id] ?? draft), [key]: value } }));
          return <article className="admin-order-card" key={order.id}><div className="admin-order-card__header"><div><span className="eyebrow">{order.order_number}</span><h3>{order.customers?.full_name || 'Cliente'}</h3><p>{new Date(order.created_at).toLocaleString('es-UY')} · {order.customers?.phone || 'Sin teléfono'}</p></div><div className="admin-order-total"><strong>{money(order.subtotal)}</strong><small>{order.shipping_cost == null ? 'Subtotal · envío a confirmar' : 'Total con envío'}</small></div></div><div className="admin-order-grid"><div><h4>Productos</h4>{(order.order_items ?? []).map((item) => <div className="order-item-mini" key={item.id}><span>{item.quantity} × {item.product_name_snapshot}{item.variant_label_snapshot ? ` · ${item.variant_label_snapshot}` : ''}</span><strong>{money(item.line_total)}</strong></div>)}<h4>Entrega</h4><p className="order-delivery">{order.customers?.locality}, {order.customers?.department}{order.customers?.address ? ` · ${order.customers.address}` : ''}{order.customers?.postal_code ? ` · CP ${order.customers.postal_code}` : ''}</p><p className="order-delivery">Transporte: {order.shipping_company_name}</p>{order.customers?.instructions && <p className="order-delivery">Nota de la clienta: {order.customers.instructions}</p>}</div><div className="admin-order-edit"><label>Estado del pedido<select value={draft.status} onChange={(e) => updateDraft('status', e.target.value)}>{orderStatuses.map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select></label><label>Estado del pago<select value={draft.payment_status} onChange={(e) => updateDraft('payment_status', e.target.value)}>{paymentStatuses.map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select></label><label>Costo de envío (UYU)<input type="number" min="0" step="0.01" placeholder="A confirmar" value={draft.shipping_cost} onChange={(e) => updateDraft('shipping_cost', e.target.value)}/></label><label>Número de seguimiento<input value={draft.tracking_number} onChange={(e) => updateDraft('tracking_number', e.target.value)} placeholder="Si existe"/></label><label>Notas internas<textarea rows={2} value={draft.internal_notes} onChange={(e) => updateDraft('internal_notes', e.target.value)}/></label><button className="button button-primary button-small button-full" onClick={() => void saveOrder(order.id)} disabled={busy}><Save size={15}/> Guardar cambios</button></div></div><div className="admin-order-footer"><span>Pago: <strong>{paymentStatuses.find(([value]) => value === order.payment_status)?.[1] || order.payment_status}</strong></span><span>Total confirmado: <strong>{order.total_amount === null || order.total_amount === undefined ? 'Pendiente de costo de envío' : money(order.total_amount)}</strong></span>{order.tracking_number && <span>Seguimiento: {order.tracking_number}</span>}</div></article>;
        })}</div> : <div className="soft-note">Todavía no hay pedidos registrados.</div>}</div></div>}

      {tab === 'reviews' && <div className="admin-panel"><div className="admin-panel__heading"><div><h2>Opiniones recibidas</h2><p>Las opiniones nuevas quedan pendientes hasta que las revises.</p></div><span className="status-pill">{(data.reviews ?? []).filter((review) => review.is_approved).length} publicadas</span></div>{(data.reviews ?? []).length ? <div className="admin-reviews-list">{(data.reviews ?? []).map((review) => <article className="admin-review-card" key={review.id}><div className="admin-review-card__heading"><div><strong>{review.display_name}</strong><span className="review-stars">{'★'.repeat(review.rating)}{'☆'.repeat(5-review.rating)}</span><small>{review.products?.name || 'Producto'} · {new Date(review.created_at).toLocaleDateString('es-UY')}</small></div><span className={`product-state${review.is_approved ? ' is-published' : ''}`}>{review.is_approved ? 'Publicada' : 'Pendiente'}</span></div><p>{review.comment}</p>{review.is_verified_purchase && <span className="verified-badge"><BadgeCheck size={15}/> Compra verificada</span>}<div className="form-actions"><button className="button button-outline button-small" onClick={() => void moderateReview(review, false)} disabled={busy}><EyeOff size={15}/> Ocultar</button>{!review.is_approved && <button className="button button-primary button-small" onClick={() => void moderateReview(review, true)} disabled={busy}><Check size={15}/> Aprobar publicación</button>}</div></article>)}</div> : <div className="soft-note">Aún no hay reseñas. Las nuevas opiniones aparecerán aquí para moderación.</div>}</div>}

      {tab === 'settings' && <div className="admin-settings-tab"><form className="admin-panel" onSubmit={(e) => { e.preventDefault(); void saveSetting('business_profile', businessForm); }}><div className="admin-panel__heading"><div><h2>Datos del negocio</h2><p>Estos datos se muestran en el sitio público.</p></div><Save size={19}/></div><div className="form-grid form-grid--two"><label>Nombre de la tienda<input required value={businessForm.name} onChange={(e) => setBusinessForm({ ...businessForm, name: e.target.value })}/></label><label>Instagram (URL)<input required type="url" value={businessForm.instagram} onChange={(e) => setBusinessForm({ ...businessForm, instagram: e.target.value })}/></label><label>Teléfono de WhatsApp<input required value={businessForm.phone} onChange={(e) => setBusinessForm({ ...businessForm, phone: e.target.value })}/></label><label>Ubicación<input value={businessForm.location} onChange={(e) => setBusinessForm({ ...businessForm, location: e.target.value })}/></label><label className="form-span-two">Mensaje de envíos<input value={businessForm.shipping_message} onChange={(e) => setBusinessForm({ ...businessForm, shipping_message: e.target.value })}/></label></div><div className="form-actions"><button className="button button-primary button-small" disabled={busy}><Save size={15}/> Guardar datos</button></div></form>
        <form className="admin-panel" onSubmit={(e) => { e.preventDefault(); void saveSetting('storefront', storefrontForm); }}><div className="admin-panel__heading"><div><h2>Portada y mensajes</h2><p>Texto del inicio de la tienda.</p></div><Save size={19}/></div><div className="form-grid"><label>Título principal<input value={storefrontForm.hero_title} onChange={(e) => setStorefrontForm({ ...storefrontForm, hero_title: e.target.value })}/></label><label>Texto de presentación<textarea rows={3} value={storefrontForm.hero_subtitle} onChange={(e) => setStorefrontForm({ ...storefrontForm, hero_subtitle: e.target.value })}/></label><label>Mensaje de anuncio<input value={storefrontForm.announcement} onChange={(e) => setStorefrontForm({ ...storefrontForm, announcement: e.target.value })}/></label><label className="toggle-line"><input type="checkbox" checked={storefrontForm.show_featured} onChange={(e) => setStorefrontForm({ ...storefrontForm, show_featured: e.target.checked })}/> Mostrar destacados</label></div><div className="form-actions"><button className="button button-primary button-small" disabled={busy}><Save size={15}/> Guardar portada</button></div></form>
        <form className="admin-panel" onSubmit={(e) => { e.preventDefault(); void saveSetting('payment_details', bankForm); }}><div className="admin-panel__heading"><div><h2>Datos de transferencia</h2><p>Se muestran solo al confirmar un pedido que eligió transferencia. No son públicos en el catálogo.</p></div><ShieldCheck size={19}/></div><div className="form-grid form-grid--two"><label>Titular<input required value={bankForm.holder} onChange={(e) => setBankForm({ ...bankForm, holder: e.target.value })}/></label><label>Banco<input required value={bankForm.bank} onChange={(e) => setBankForm({ ...bankForm, bank: e.target.value })}/></label><label>Número de cuenta<input required value={bankForm.account_number} onChange={(e) => setBankForm({ ...bankForm, account_number: e.target.value })}/></label><label>Instrucciones<textarea rows={3} value={bankForm.instructions} onChange={(e) => setBankForm({ ...bankForm, instructions: e.target.value })}/></label></div><div className="form-actions"><button className="button button-primary button-small" disabled={busy}><Save size={15}/> Guardar datos de pago</button></div></form>
        <div className="admin-panel"><div className="admin-panel__heading"><div><h2>Categorías</h2><p>Activá o desactivá las categorías del catálogo.</p></div></div><div className="category-admin-list">{(data.categories ?? []).map((category) => <div className="category-admin-row" key={category.id}><span>{category.name}</span><label className="toggle-line"><input type="checkbox" checked={category.is_active !== false} onChange={(e) => void saveCategory({ ...category, is_active: e.target.checked })}/> Activa</label></div>)}</div><form className="inline-create" onSubmit={(e) => { e.preventDefault(); void saveCategory(); }}><input required value={newCategory} onChange={(e) => setNewCategory(e.target.value)} placeholder="Nombre de nueva categoría"/><button className="button button-outline button-small" disabled={busy}><Plus size={15}/> Agregar</button></form></div>
        <div className="admin-panel"><div className="admin-panel__heading"><div><h2>Empresas y costos de envío</h2><p>Los costos pueden quedar pendientes hasta confirmar la tarifa real.</p></div></div><div className="shipping-admin-list">{(data.shipping ?? []).map((row) => { const draft = shippingDrafts[row.id] ?? { name: row.name, is_active: row.is_active, cost_mode: row.cost_mode, cost: row.cost === null ? '' : String(row.cost), estimated_days: row.estimated_days || '' }; const upd = (key: keyof typeof draft, value: string | boolean) => setShippingDrafts((current) => { const previous = current[row.id] ?? draft; const next = { ...previous }; if (key === 'is_active') next.is_active = Boolean(value); else if (key === 'cost_mode') next.cost_mode = value as ShippingRow['cost_mode']; else if (key === 'name') next.name = String(value); else if (key === 'cost') next.cost = String(value); else next.estimated_days = String(value); return { ...current, [row.id]: next }; }); return <div className="shipping-admin-row" key={row.id}><div className="shipping-admin-row__name"><strong>{row.name}</strong><label className="toggle-line"><input type="checkbox" checked={draft.is_active} onChange={(e) => upd('is_active', e.target.checked)}/> Activa</label></div><div className="shipping-admin-row__fields"><label>Tarifa<select value={draft.cost_mode} onChange={(e) => upd('cost_mode', e.target.value)}><option value="confirm">A confirmar</option><option value="fixed">Fija</option><option value="free">Gratis</option></select></label><label>Costo (UYU)<input type="number" min="0" step="0.01" value={draft.cost} disabled={draft.cost_mode !== 'fixed'} onChange={(e) => upd('cost', e.target.value)}/></label><label>Plazo orientativo<input value={draft.estimated_days} onChange={(e) => upd('estimated_days', e.target.value)} placeholder="Opcional"/></label><button className="button button-outline button-small" onClick={() => void saveShipping(row)} disabled={busy}><Save size={14}/> Guardar</button></div></div>; })}</div></div>
        <section className="admin-panel"><div className="admin-panel__heading"><div><h2>Preguntas frecuentes</h2><p>Estas respuestas se mostrarán en la página pública de preguntas frecuentes.</p></div><ClipboardList size={19}/></div>{faqDrafts.map((item, index) => <div className="faq-admin-item" key={`faq-${index}`}><div className="faq-admin-item__heading"><strong>Pregunta {index + 1}</strong><button type="button" className="button button-outline button-small" onClick={() => setFaqDrafts((current) => current.filter((_, i) => i !== index))}><Trash2 size={14}/> Quitar</button></div><label>Pregunta<input maxLength={240} value={item.question} onChange={(e) => setFaqDrafts((current) => current.map((row, i) => i === index ? { ...row, question: e.target.value } : row))}/></label><label>Respuesta<textarea rows={3} maxLength={1800} value={item.answer} onChange={(e) => setFaqDrafts((current) => current.map((row, i) => i === index ? { ...row, answer: e.target.value } : row))}/></label></div>)}<div className="form-actions"><button type="button" className="button button-outline button-small" onClick={() => setFaqDrafts((current) => [...current, { question: '', answer: '' }])}><Plus size={15}/> Agregar pregunta</button><button type="button" className="button button-primary button-small" disabled={busy || faqDrafts.some((item) => !item.question.trim() || !item.answer.trim())} onClick={() => void saveSetting('faq', { items: faqDrafts })}><Save size={15}/> Guardar preguntas</button></div></section>
        <section className="admin-panel"><div className="admin-panel__heading"><div><h2>Promociones de la tienda</h2><p>Creá avisos temporales que se mostrarán en la portada mientras estén activos y dentro de sus fechas.</p></div><Star size={19}/></div><form onSubmit={(e) => void savePromotion(e)}><div className="form-grid form-grid--two"><label>Título de la promoción<input required minLength={2} maxLength={120} value={promotionDraft.title} onChange={(e) => setPromotionDraft({ ...promotionDraft, title: e.target.value })}/></label><label>Descripción<textarea rows={2} maxLength={700} value={promotionDraft.description} onChange={(e) => setPromotionDraft({ ...promotionDraft, description: e.target.value })}/></label><label>Válida desde<input type="datetime-local" value={promotionDraft.starts_at} onChange={(e) => setPromotionDraft({ ...promotionDraft, starts_at: e.target.value })}/></label><label>Válida hasta<input type="datetime-local" value={promotionDraft.ends_at} onChange={(e) => setPromotionDraft({ ...promotionDraft, ends_at: e.target.value })}/></label><label className="toggle-line"><input type="checkbox" checked={promotionDraft.is_active} onChange={(e) => setPromotionDraft({ ...promotionDraft, is_active: e.target.checked })}/> Activa</label></div><div className="form-actions"><button className="button button-primary button-small" disabled={busy}><Save size={15}/>{promotionDraft.id ? 'Guardar cambios' : 'Crear promoción'}</button>{promotionDraft.id && <button type="button" className="button button-outline button-small" onClick={() => setPromotionDraft({ id: '', title: '', description: '', starts_at: '', ends_at: '', is_active: false })}>Cancelar edición</button>}</div></form><div className="promotion-admin-list">{(data.promotions ?? []).length ? (data.promotions ?? []).map((promotion) => <article className="admin-review-card" key={promotion.id}><div className="admin-review-card__heading"><div><strong>{promotion.title}</strong><p>{promotion.description || 'Sin descripción'}</p><small>{promotion.starts_at ? new Date(promotion.starts_at).toLocaleString('es-UY') : 'Desde ahora'} · {promotion.ends_at ? new Date(promotion.ends_at).toLocaleString('es-UY') : 'Sin fecha final'}</small></div><span className={`product-state${promotion.is_active ? ' is-published' : ''}`}>{promotion.is_active ? 'Activa' : 'Inactiva'}</span></div><div className="form-actions"><button type="button" className="button button-outline button-small" onClick={() => setPromotionDraft({ id: promotion.id, title: promotion.title, description: promotion.description || '', starts_at: dateTimeLocal(promotion.starts_at), ends_at: dateTimeLocal(promotion.ends_at), is_active: promotion.is_active })}><Pencil size={14}/> Editar</button><button type="button" className="button button-outline button-small" onClick={() => void deletePromotion(promotion)} disabled={busy}><Trash2 size={14}/> Eliminar</button></div></article>) : <div className="soft-note">Todavía no hay promociones registradas.</div>}</div></section>
        <form className="admin-panel" onSubmit={(e) => { e.preventDefault(); void saveSettingsBatch([{ key: 'policy_privacy', value: { title: 'Política de privacidad', content: policyDrafts.policy_privacy, needs_review: true } }, { key: 'policy_terms', value: { title: 'Condiciones de compra', content: policyDrafts.policy_terms, needs_review: true } }, { key: 'policy_returns', value: { title: 'Cambios y devoluciones', content: policyDrafts.policy_returns, needs_review: true } }]); }}><div className="admin-panel__heading"><div><h2>Textos legales</h2><p>Plantillas editables. Revisalas antes de publicar, de acuerdo con las prácticas reales y normativa aplicable.</p></div><AlertTriangle size={19}/></div><label>Política de privacidad<textarea rows={5} value={policyDrafts.policy_privacy} onChange={(e) => setPolicyDrafts({ ...policyDrafts, policy_privacy: e.target.value })} placeholder="Escribí la política de privacidad…"/></label><label>Condiciones de compra<textarea rows={5} value={policyDrafts.policy_terms} onChange={(e) => setPolicyDrafts({ ...policyDrafts, policy_terms: e.target.value })} placeholder="Escribí las condiciones de compra…"/></label><label>Cambios y devoluciones<textarea rows={5} value={policyDrafts.policy_returns} onChange={(e) => setPolicyDrafts({ ...policyDrafts, policy_returns: e.target.value })} placeholder="Escribí la política de cambios y devoluciones…"/></label><div className="form-actions"><button className="button button-primary button-small" disabled={busy}><Save size={15}/> Guardar textos legales</button></div></form>
      </div>}
    </section>
  </main>;
}
